id_t target_pid = 1234;  // Example PID
int high_nice_value = -10;  // Range: -20 (highest) to 19 (lowest)
int result;

// Set priority for a specific process (PID 1234)
result = setpriority(PRIO_PROCESS, target_pid, high_nice_value);

// Set priority for the calling process (PID 0) to standard (nice 0)
result = setpriority(PRIO_PROCESS, 0, 0);

// Set priority for all processes owned by the current effective user
result = setpriority(PRIO_USER, 0, 5); // ID 0 means current user

// Error check: result == -1 indicates failure (e.g., EPERM)
// Must be root/CAP_SYS_NICE to set nice_value < 0.
